def update(self, iterable):
        """Update the ManyToMany with key-value pairs from an iterable.

        Args:
            iterable: An iterable of (key, value) pairs or a dict-like object
        """
        if hasattr(iterable, 'items'):
            # Handle dict-like objects
            for key, vals in iterable.items():
                if hasattr(vals, '__iter__') and not isinstance(vals, str):
                    # vals is an iterable of values
                    for val in vals:
                        self.add(key, val)
                else:
                    # vals is a single value
                    self.add(key, vals)
        else:
            # Handle iterable of (key, value) pairs
            for key, val in iterable:
                self.add(key, val)

