def make_safe_absolute_uri(base, rel=None):
    # Handle edge cases where base is None or empty
    if not base:
        return rel if rel else ''

    # Handle edge case where rel is None or empty
    if not rel:
        return base if base else ''

    # Join the base and relative URLs
    absolute_uri = _urljoin(base, rel)

    # If urljoin returned empty string, return it
    if not absolute_uri:
        return ''

    # Check if ACCEPTABLE_URI_SCHEMES is defined and non-empty
    # If it's empty or not defined, skip scheme checking
    try:
        if not ACCEPTABLE_URI_SCHEMES:
            return absolute_uri
    except NameError:
        # ACCEPTABLE_URI_SCHEMES is not defined
        return absolute_uri

    # Extract and validate the scheme
    parsed = urllib.parse.urlparse(absolute_uri)

    # If scheme exists and is not in acceptable schemes, return empty string
    if parsed.scheme and parsed.scheme not in ACCEPTABLE_URI_SCHEMES:
        return ''

    return absolute_uri

def get_tunings(instrument=None, nr_of_strings=None, nr_of_courses=None):
    """Return a list of tunings.

    If instrument is None, return all tunings; otherwise return tunings for
    the given instrument. The instrument argument is treated like a
    case-insensitive prefix.

    The nr_of_strings and nr_of_courses parameters can be used to filter on
    the number of strings or courses.

    Example:
    >>> get_tunings()
    [<StringTuning instance at 0x1>, ...]
    >>> get_tunings('guitar')
    [<StringTuning instance at 0x2>, ...]
    >>> get_tunings('guitar', 6)
    [<StringTuning instance at 0x3>, ...]
    """
    result = []

    if instrument is None:
        # Return all tunings
        for (instr_name, tunings_dict) in six.itervalues(_known):
            for tuning in six.itervalues(tunings_dict):
                if nr_of_strings is None and nr_of_courses is None:
                    result.append(tuning)
                elif nr_of_strings is not None and nr_of_courses is None:
                    if tuning.count_strings() == nr_of_strings:
                        result.append(tuning)
                elif nr_of_strings is None and nr_of_courses is not None:
                    if tuning.count_courses() == nr_of_courses:
                        result.append(tuning)
                else:
                    if (tuning.count_courses() == nr_of_courses and 
                        tuning.count_strings() == nr_of_strings):
                        result.append(tuning)
    else:
        # Filter by instrument
        searchi = str.upper(instrument)
        keys = list(_known.keys())
        for x in keys:
            if (searchi not in keys and x.find(searchi) == 0 or 
                searchi in keys and x == searchi):
                for tuning in six.itervalues(_known[x][1]):
                    if nr_of_strings is None and nr_of_courses is None:
                        result.append(tuning)
                    elif nr_of_strings is not None and nr_of_courses is None:
                        if tuning.count_strings() == nr_of_strings:
                            result.append(tuning)
                    elif nr_of_strings is None and nr_of_courses is not None:
                        if tuning.count_courses() == nr_of_courses:
                            result.append(tuning)
                    else:
                        if (tuning.count_courses() == nr_of_courses and 
                            tuning.count_strings() == nr_of_strings):
                            result.append(tuning)

    return result

